class _Rec:
    """Stub client factory: records the exact call instead of building a client."""

    def __init__(self, tag):
        self.tag = tag

    def __call__(self, *args, **kwargs):
        return (self.tag, args, kwargs)


@pytest.fixture
def stubs(monkeypatch, caplog):
    monkeypatch.setattr(cfg, "ChatOpenAI", _Rec("ChatOpenAI"))
    monkeypatch.setattr(cfg, "init_chat_model", _Rec("init_chat_model"))
    monkeypatch.setattr(langchain_deepseek, "ChatDeepSeek", _Rec("ChatDeepSeek"))
    monkeypatch.setattr(cfg, "THINKING_MODE", "auto")
    caplog.set_level(logging.WARNING, logger="model_fallback")

    def set_keys(keys):
        for k in _ALL_KEYS:
            monkeypatch.delenv(k, raising=False)
        for k in keys:
            monkeypatch.setenv(k, "k-" + k)

    def call(model, **kwargs):
        caplog.clear()
        try:
            res = cfg.get_model(model, **kwargs)
        except Exception as e:  # recorded, compared against the original's error
            return ("ERR", type(e).__name__, str(e))
        logs = tuple(r.getMessage() for r in caplog.records if r.name == "model_fallback")
        return res + (logs,)

    return set_keys, call


def _case_id(i):
    model, keys, kwargs, grt, _ = CASES[i]
    ks = "FULL" if keys == FULL else "+".join(k.split("_")[0] for k in keys) or "nokeys"
    kw = ",".join(f"{k}={v!r}" for k, v in kwargs.items())
    return f"{i}-{model}-{ks}-grt={grt}-{kw}"


def test_cases_cover_enough():
    assert len(CASES) >= 300
    assert len(REQUIRED_KEYS) >= 45


@pytest.mark.parametrize("name", list(REQUIRED_KEYS))
@pytest.mark.parametrize("route", [False, True])
def test_model_required_keys_unchanged(name, route):
    assert cfg.model_required_keys(name, route) == REQUIRED_KEYS[name][route]


@pytest.mark.parametrize("i", range(len(CASES)), ids=[_case_id(i) for i in range(len(CASES))])
def test_get_model_call_unchanged(stubs, monkeypatch, i):
    set_keys, call = stubs
    model, keys, kwargs, grt, expected = CASES[i]
    set_keys(keys)
    monkeypatch.setattr(cfg, "ROUTE_VIA_OPENROUTER", grt)
    assert call(model, **kwargs) == expected


def test_alternative_key_spellings_preserved():
    assert cfg.model_required_keys("deepseek-v4-pro") == ["DEEPSEEK_API_KEY", "DEEPSEEK_KEY"]
    assert cfg.model_required_keys("gemini-3-flash-preview") == ["GEMINI_API_KEY", "GOOGLE_API_KEY"]


def test_missing_key_messages(stubs):
    set_keys, call = stubs
    set_keys([])
    err = call("deepseek-v4-pro", route_via_openrouter=False)
    assert err == ("ERR", "ValueError",
                   "DEEPSEEK_API_KEY (or DEEPSEEK_KEY) not found in .env for model 'deepseek-v4-pro'. "
                   "Add the key or set the model chain to a provider you have a key for.")
    err = call("glm-5.2", route_via_openrouter=False)
    assert err[:2] == ("ERR", "ValueError") and err[2].startswith("ZHIPUAI_API_KEY not found")
    err = call("mimo-v2.5", route_via_openrouter=True)
    assert err[2].startswith("OPENROUTER_API_KEY not found")


def test_unknown_model_error(stubs):
    set_keys, call = stubs
    set_keys(FULL)
    err = call("claude-sonnet-4", route_via_openrouter=False)
    assert err[:2] == ("ERR", "ValueError")
    assert err[2].startswith("Cannot determine provider for model: claude-sonnet-4. Supported providers:")


def test_invalid_reasoning_effort_error(stubs):
    set_keys, call = stubs
    set_keys(FULL)
    assert call("deepseek-v4-flash", reasoning_effort="bogus") == (
        "ERR", "ValueError", "Invalid reasoning_effort: 'bogus'. Use 'low', 'medium', or 'high'.")


@pytest.mark.parametrize("const,model,route,expected_url", [
    ("MIMO_BASE_URL", "mimo-v2.5", False, "https://patched.example/mimo/v1"),
    ("MIMO_BASE_URL", "mimo-v2.6-custom", False, "https://patched.example/mimo/v1"),
    ("META_BASE_URL", "muse-spark-1.2", False, "https://patched.example/meta/v1"),
    ("OPENROUTER_BASE_URL", "deepseek-baba-singapore", False, "https://patched.example/or/v1"),
    ("OPENROUTER_BASE_URL", "deepseek-baba-singapore", True, "https://patched.example/or/v1"),
])
def test_base_url_constants_read_at_call_time(stubs, monkeypatch, const, model, route, expected_url):
    """The original read these module globals on every call; patching must be honoured."""
    set_keys, call = stubs
    set_keys(FULL)
    monkeypatch.setattr(cfg, const, expected_url)
    res = call(model, route_via_openrouter=route)
    assert res[0] == "ChatOpenAI"
    assert res[2]["base_url"] == expected_url


def test_openrouter_slug_route_and_literal_urls_ignore_patched_constants(stubs, monkeypatch):
    """Rows/branches whose URL was a literal in the original stay literal."""
    set_keys, call = stubs
    set_keys(FULL)
    for const in ("MIMO_BASE_URL", "META_BASE_URL", "OPENROUTER_BASE_URL"):
        monkeypatch.setattr(cfg, const, "https://patched.example/x")
    assert call("mimo-v2.5", route_via_openrouter=True)[2]["base_url"] == "https://openrouter.ai/api/v1"
    assert call("meta/muse-spark-1.2", route_via_openrouter=False)[2]["base_url"] == "https://openrouter.ai/api/v1"
    assert call("nvidia/nemotron-3.5-lightning")[2]["base_url"] == "https://openrouter.ai/api/v1"
    assert call("glm-5.2", route_via_openrouter=False)[2]["base_url"] == "https://api.z.ai/api/paas/v4/"
    assert call("deepseek-v4-pro", route_via_openrouter=False)[2]["api_base"] == "https://api.deepseek.com/v1"
